var current = null;

function el(tag, cls, text) {
    var e = document.createElement(tag);
    if (cls) e.className = cls;
    if (text !== undefined) e.textContent = text;
    return e;
}
function norm(s) { return String(s).toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, ''); }
function brandById(id) {
    for (var i = 0; i < BRANDS.length; i++) if (BRANDS[i].id === id) return BRANDS[i];
    return null;
}
function countItems(b) {
return b.cats.reduce(function (n, c) { return n + c.items.length; }, 0);
}
function paint(node, b) {
    node.style.setProperty('--b-bg', b.bg);
    node.style.setProperty('--b-fg', b.fg);
    node.style.setProperty('--b-ac', b.ac);
}

function buildTiles() {
    var box = document.getElementById('tiles');
    BRANDS.forEach(function (b) {
    var t = el('button', 'tile');
    t.type = 'button';
    t.id = 'tile-' + b.id;
    t.setAttribute('role', 'tab');
    t.setAttribute('aria-selected', 'false');
    paint(t, b);
    if (b.logo) {
        var img = document.createElement('img');
        img.src = b.logo; img.alt = b.alt;
        t.appendChild(img);
    } else {
        t.appendChild(el('span', 'word', b.name));
    }
    t.appendChild(el('span', 'meta', countItems(b) + ' platos'));
    t.addEventListener('click', function () { select(b.id, true); });
    box.appendChild(t);
    });
}

function select(id, setHash) {
    var b = brandById(id);
    if (!b || (current && current.id === b.id)) return;
    var first = current === null;
    current = b;
    BRANDS.forEach(function (x) {
    document.getElementById('tile-' + x.id).setAttribute('aria-selected', x.id === b.id ? 'true' : 'false');
    });
    var panel = document.getElementById('panel');
    paint(panel, b);
    var head = document.getElementById('bname');
    head.textContent = '';
    head.appendChild(el('span', 'dot'));
    head.appendChild(document.createTextNode(b.name));
    document.getElementById('btag').textContent = b.tagline;
    document.getElementById('q').value = '';
    renderChips();
    renderMenu();
    if (!first) {
    panel.classList.remove('fade');
    void panel.offsetWidth;
    panel.classList.add('fade');
    }
    if (setHash) { try { location.hash = b.id; } catch (e) {} }
}

function renderChips() {
    var box = document.getElementById('chips');
    box.textContent = '';
    document.getElementById('barwrap').hidden = current.cats.length < 2;
    current.cats.forEach(function (c) {
    var b = el('button', 'chip', c.title);
    b.type = 'button';
    b.addEventListener('click', function () {
        var s = document.getElementById('cat-' + c.id);
        if (s) s.scrollIntoView({ behavior: 'smooth', block: 'start' });
    });
    box.appendChild(b);
    });
}

function renderMenu() {
    var root = document.getElementById('menu');
    root.textContent = '';
    var q = norm(document.getElementById('q').value.trim());
    var shown = 0;
    current.cats.forEach(function (c) {
    var list = c.items.filter(function (i) { return !q || norm(i[0] + ' ' + i[1]).indexOf(q) >= 0; });
    if (!list.length) return;
    shown += list.length;
    var s = el('section', 'cat');
    s.id = 'cat-' + c.id;
    var h = el('h3', 'title', c.title);
    h.appendChild(el('span', 'count', list.length === 1 ? '1 plato' : list.length + ' platos'));
    s.appendChild(h);
    if (c.note) s.appendChild(el('p', 'note', c.note));
    var grid = el('div', 'items');
    list.forEach(function (i) {
        var it = el('div', 'item');
        var row = el('div', 'row');
        row.appendChild(el('h4', 'name', i[0]));
        if (i[2] === null || i[2] === undefined) {
        row.appendChild(el('span', 'consult', 'Consultar precio'));
        } else {
        var pb = el('div', 'pricebox');
        if (i[3]) pb.appendChild(el('span', 'size', i[3]));
        pb.appendChild(el('span', 'price', 'Bs ' + i[2]));
        row.appendChild(pb);
        }
        it.appendChild(row);
        it.appendChild(el('p', 'desc', i[1]));
        grid.appendChild(it);
    });
    s.appendChild(grid);
    root.appendChild(s);
    });
    if (!shown) root.appendChild(el('p', 'empty', 'No encontramos ese plato en esta carta.'));
}

buildTiles();
document.getElementById('q').addEventListener('input', renderMenu);
window.addEventListener('hashchange', function () { select(location.hash.slice(1), false); });
select(brandById(location.hash.slice(1)) ? location.hash.slice(1) : BRANDS[0].id, false);
